{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Meridian Health Partners, Inc."],
   "quote": "This Master Services Agreement is made effective 5 June 2025 between Northwind Labs, Inc. (\"Northwind\") and Meridian Health Partners, Inc. (\"Meridian\")"
  },
  "counterparty": {
   "value": "Meridian Health Partners, Inc.",
   "quote": "Meridian Health Partners, Inc. (\"Meridian\")"
  },
  "effective_date": {
   "value": "2025-06-05",
   "quote": "This Master Services Agreement is made effective 5 June 2025"
  },
  "term_months": {
   "value": 24,
   "quote": "This Agreement will remain in effect for 24 months from the Effective Date."
  },
  "auto_renewal": {
   "value": false,
   "quote": "The Parties may extend this Agreement by mutual written agreement."
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "England and Wales",
   "quote": "This Agreement shall be governed by and construed in accordance with the laws of England and Wales"
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": 30,
   "quote": "Northwind shall pay all undisputed invoices within thirty (30) days of receipt."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": true,
   "quote": "Either Party may terminate this Agreement for convenience upon 30 days' prior written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Lena Fischer",
   "email": "lena.fischer@meridian.example",
   "title": "Chief Operating Officer",
   "party": "Meridian Health Partners, Inc."
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "high",
   "message": "The agreement has no limitation of liability clause, so Northwind's exposure (and Meridian's) is uncapped and there are no exclusions for indirect or consequential damages.",
   "quote": "17. INDEMNIFICATION\nMeridian shall indemnify and hold harmless Northwind from third-party claims arising from the Services."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "high",
   "message": "There is no confidentiality clause, so Northwind's confidential information shared with Meridian (a health-sector vendor) is not contractually protected.",
   "quote": "This Agreement constitutes the entire agreement between the Parties and supersedes all prior discussions relating to its subject matter."
  },
  {
   "id": "no_ip_or_data_protection_terms",
   "severity": "medium",
   "message": "The agreement does not address ownership of work product or data protection, which matters for services provided by a health-sector vendor.",
   "quote": "Meridian will provide professional services to Northwind under one or more Statements of Work."
  },
  {
   "id": "fees_deferred_to_sow",
   "severity": "low",
   "message": "No fees or spending cap are stated in the MSA, so cost exposure depends entirely on each Statement of Work.",
   "quote": "Fees for the Services are set out in each Statement of Work."
  },
  {
   "id": "term_expired",
   "severity": "medium",
   "message": "The 24-month term from 5 June 2025 ended on about 5 June 2027, and there is no auto-renewal; any continued services need a written extension.",
   "quote": "The Parties may extend this Agreement by mutual written agreement."
  },
  {
   "id": "narrow_indemnity",
   "severity": "low",
   "message": "The indemnity is one-way in Northwind's favour but covers only third-party claims arising from the Services. It has no defence obligations, procedure or carve-outs.",
   "quote": "Meridian shall indemnify and hold harmless Northwind from third-party claims arising from the Services."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a 24-month Master Services Agreement between Northwind Labs, Inc. and Meridian Health Partners, Inc., effective 5 June 2025 and governed by the laws of England and Wales. Either party may terminate on 30 days' notice, but the contract has no liability cap or confidentiality terms, and the fees are left to separate Statements of Work."
}
